assert tau_lo*tau_lo < c/(2*pi_hi)
assert tau_hi*tau_hi > c/(2*pi_lo)
def mhe(i,j,tau):
    if (i+j)%2==0:
        return F(factorial(i))*r**i/2 if i==j else F(0)
    out=F(0)
    for k in range(min(i,j)+1):
        n=i+j-2*k; m=(n-1)//2
        half=-F(((-1)**m)*factorial(2*m),2**m*factorial(m))
        coeff=F(factorial(i)*factorial(j),factorial(k)*factorial(i-k)*factorial(j-k))
        out += coeff*r**k*c**m*half
    return tau*out
def full_BG(tau):
    nrow=len(Q); ncol=len(Q[0])
    M=[[mhe(i,j,tau) for j in range(nrow)] for i in range(nrow)]
    B=[[F(0)]*ncol for _ in range(ncol)]; G=[[F(0)]*ncol for _ in range(ncol)]
    for a in range(ncol):
      for b in range(ncol):
        G[a][b]=sum(F(Q[i][a]*Q[i][b]*factorial(i)) for i in range(nrow))
        B[a][b]=sum(F(Q[i][a]*Q[j][b])*M[i][j] for i in range(nrow) for j in range(nrow))
    return B,G
def ldlt(A):
    n=len(A); L=[[F(0)]*n for _ in range(n)]; D=[F(0)]*n
    for i in range(n):
      L[i][i]=1
      z=A[i][i]-sum(L[i][k]*L[i][k]*D[k] for k in range(i))
      if z<=0: return None
      D[i]=z
      for j in range(i+1,n):
        z=A[j][i]-sum(L[j][k]*L[i][k]*D[k] for k in range(i)); L[j][i]=z/D[i]
    return D
targets=[(3,F(277,500)),(4,F(4287,10000)),(5,F(3309,10000)),(6,F(2549,10000)),(7,F(49,250)),(8,F(301,2000)),(9,F(577,5000)),(10,F(221,2500)),(11,F(169,2500)),(12,F(517,10000)),(13,F(79,2000)),(14,F(301,10000)),(15,F(57,2500))]
for tau in (tau_lo,tau_hi):
  B,G=full_BG(tau)
  for k,a in targets:
    D=ldlt([[B[i][j]-a*G[i][j] for j in range(k)] for i in range(k)])
    assert D is not None,(tau,k,a)
    print(float(tau),k,float(a),float(min(D)))
L=sum(a**4 for _,a in targets)+r**(8*15)/(F(16)*(1-r**8))
print('L30',L,float(L))
print('PASS')

# Synthesis with inherited scale-safe fourth trace and degree-48 quasimode.
trace4=F(54959,50000)
mu_lo=F(91219830,100000000)
mu_hi=F(91219831,100000000)
eps2_hi=F(25851,1000000000)
theta=F(34357,200000)  # 0.171785
x=F(1140411,1250000)   # 0.9123288
beta=F(14281,20000)    # 0.71405
# 4 theta=34357/50000, hence x<r^(4 theta) iff x^50000<r^34357.
assert x**50000 < r**34357
assert x>mu_hi and mu_lo>beta
trace_margin=beta**4-(trace4-x**4-L)
assert trace_margin>0
temple_margin=(x-mu_hi)*(mu_lo-beta)-eps2_hi
assert temple_margin>0
# Recheck the exact all-lag covariance bridge finite core k=1,...,5.
cov_margins=[]
for kk in range(1,6):
    u=r**kk; tk=c*r**(kk-1)
    AA=6*u**5*tk+2*u**10-5*u**6-5*u**4+2
    margin=AA*AA-4*(1-u**4)**5
    assert AA>0 and margin>0
    cov_margins.append(margin)
# For k>=6, inherited polynomial tail proof uses z<=1/4 and Q(z)>=1.
assert c/r>1
assert F(4)-F(7,4)-F(20,16)==F(1)
old=F(21473,125000)
source_upper=F(1,4)
assert theta>old and source_upper-theta < source_upper-old
print('synthesis theta old/new =',old,theta,float(old),float(theta))
print('trace margin =',trace_margin,float(trace_margin))
print('Temple margin =',temple_margin,float(temple_margin))
print('covariance finite margins =',[float(z) for z in cov_margins])
print('old/new source gaps =',float(source_upper-old),float(source_upper-theta))
print('source gain =',theta-old,float(theta-old))
print('ALL_EXACT_CHECKS_PASS = True')